561:     pub(crate) fn gather<Src: M, IndexedAxis: M, Dst: M, Idx: M>(
562:         &self,
563:         dst: &mut BufStorage<D, B>,
564:         index: &BufStorage<i32, B>,
565:         domain: &Mapping,
566:         chip: &Mapping,
567:         prefix: Option<usize>,
568:         unit: IndexUnit,
569:     ) where
570:         D: MaterializableScalar,
571:         B: Sync,
572:     {
573:         let table = in_chip_elements(&Src::to_value(), chip);
574:         let output = in_chip_elements(&Dst::to_value(), chip);
575:         let indexed_axis = IndexedAxis::to_value();
576: 
577:         let domain_size = domain.iter_positions().flatten().count();
578:         let indexed_axis_size = indexed_axis.iter_positions().flatten().count();
579:         // DMA may execute past the prefix, so every index value must be valid.
580:         let index_positions =
581:             axis_positions_by_chip(index, &Idx::to_value(), chip, unit, indexed_axis_size, domain_size);
582: 
583:         let source_by_output = {
584:             let payload = table
585:                 .remove_axis(&indexed_axis)
586:                 .unwrap_or_else(|error| {
587:                     panic!("gather table {table} does not hold {indexed_axis} as one region: {error}")
588:                 })
589:                 .normalize();
590:             let table_offsets = live_offsets_by(
591:                 &table,
592:                 &payload,
593:                 &indexed_axis,
594:                 "gather: table factors into payload x indexed axis",
595:             );
596:             let output_offsets = live_offsets_by(
597:                 &output,
598:                 &payload,
599:                 domain,
600:                 "gather: output factors into payload x domain",
601:             );
602:             let requested = prefix.unwrap_or(domain_size).min(domain_size);
603:             let mut source_by_output = vec![None; dst.len()];
604:             for (physical_chip, positions) in index_positions.iter().enumerate() {
605:                 let Some(positions) = positions else { continue };
606:                 let table_base = physical_chip * table.size();
607:                 let output_base = physical_chip * output.size();
608:                 // Matching rows retain the payload coordinate while replacing the indexed axis with domain.
609:                 for (table_row, output_row) in table_offsets
610:                     .chunks_exact(indexed_axis_size)
611:                     .zip(output_offsets.chunks_exact(domain_size))
612:                 {
613:                     for (domain_position, &output_offset) in output_row.iter().take(requested).enumerate() {
614:                         let indexed_position = positions[domain_position];
615:                         let table_offset = table_base + table_row[indexed_position];
616:                         let output_offset = output_base + output_offset;
617:                         assert!(
618:                             source_by_output[output_offset].is_none(),
619:                             "destination slot {output_offset} is written by two stream positions"
620:                         );
621:                         source_by_output[output_offset] = Some(table_offset);
622:                     }
623:                 }
624:             }
625:             source_by_output
626:         };
