37: pub enum IndexMapping<'a> {
38:     /// Byte offsets held in an HBM tensor, whose element mapping is the index domain.
39:     ByteOffsets(&'a Mapping),
40:     /// Unscaled positions held in an SPM tensor, whose live axes are the index domain.
41:     SpmPositions(SpmPlacement<'a>),
42: }
43: 
44: impl IndexMapping<'_> {
45:     /// The domain the index carries: the list, with the cluster in front where each cluster holds
46:     /// its own.
47:     ///
48:     /// A cluster that holds one copy names nothing, the way the PE placement never does. Every
49:     /// other cluster gives each of its positions a list, and joins the domain as it is written.
50:     pub fn domain(self) -> Result<Mapping, IndexPaddingError> {
51:         match self {
52:             Self::ByteOffsets(offsets) => {
53:                 ensure_unpadded(offsets)?;
54:                 Ok(offsets.clone().normalize())
55:             }
56:             Self::SpmPositions(index) => {
57:                 ensure_unpadded(index.element)?;
58:                 let list = index.element.clone().normalize();
59:                 if holds_one_copy(index.cluster) {
60:                     return Ok(list);
61:                 }
62:                 Ok(index.cluster.clone().pair(list).normalize())
63:             }
64:         }
65:     }
66: }
