213:     /// Pairs two mappings, dropping an identity operand rather than nesting it (`[1, X] == X`).
214:     /// The single source of truth shared by `MappingExt::pair` (above the FFI) and the impl
215:     /// crate's `mapping_pair` (the factorize path), so the two cannot diverge.
216:     pub fn pair(self, other: Self) -> Self {
217:         if self == Self::identity() {
218:             other
219:         } else if other == Self::identity() {
220:             self
221:         } else {
222:             Self::Pair {
223:                 left: RBox::new(self),
224:                 right: RBox::new(other),
225:             }
226:         }
227:     }
