229:     /// The cell count this mapping reads. Tolerates a ragged `Stride` / `Modulo` (one whose
230:     /// divisor does not divide the inner size), which the matcher emits as a valid OUTPUT
231:     /// even though it is not a valid `from_mapping` INPUT.
232:     pub fn size(&self) -> usize {
233:         match self {
234:             Self::Symbol { size, .. } => *size,
235:             Self::Stride { inner, stride } => inner.size() / stride,
236:             Self::Modulo { modulo, .. } => *modulo,
237:             Self::Resize { resize, .. } => *resize,
238:             Self::Padding { padding, .. } => *padding,
239:             Self::Pair { left, right } => left.size() * right.size(),
240:             Self::Broadcast { size } => *size,
241:         }
242:     }
